/**
 * Regenerates src/data/commonWordsRomanization.ts from the built-in Common Words.
 * Run after adding or changing words:  npm run words:romanize
 */
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { COMMON_WORDS } from "../src/data/commonWords";
import { romanizeCommonWord } from "./commonWordsRomanizer";

const spellings = [...new Set(COMMON_WORDS.map((w) => w.spelling))];
const lines = spellings.map((s) => `  ${JSON.stringify(s)}: ${JSON.stringify(romanizeCommonWord(s))},`);
const out = [
  "// GENERATED by `npm run words:romanize` (scripts/romanize-common-words.ts). Do not edit by hand:",
  "// fix romanizations in scripts/commonWordsRomanizer.ts (ROMANIZATION_OVERRIDES) and re-run.",
  "export const COMMON_WORD_ROMANIZATION: Record<string, string> = {",
  ...lines,
  "};",
  "",
].join("\n");

const target = fileURLToPath(new URL("../src/data/commonWordsRomanization.ts", import.meta.url));
writeFileSync(target, out, "utf8");
console.log(`Wrote ${spellings.length} romanizations to ${target}`);
